def check_balance(m):
    # Check rows
    for r in range(n):
        counts = [0, 0, 0]
        for val in m[r]:
            counts[val] += 1
        if counts[0] != counts[1] or counts[1] != counts[2]:
            return False, f"Row {r} unbalanced: {counts}"

    # Check columns
    for c in range(n):
        counts = [0, 0, 0]
        for r in range(n):
            counts[m[r][c]] += 1
        if counts[0] != counts[1] or counts[1] != counts[2]:
            return False, f"Col {c} unbalanced: {counts}"

    # Check diagonals (Anti-Diagonals: i+j=k)
    # k ranges from 0 to 2n-2 = 4
    for k in range(2 * n - 1):
        diag = []
        for i in range(n):
            j = k - i
            if 0 <= j < n:
                diag.append(matrix[i][j])

        L = len(diag)
        if L > 0 and L % 3 == 0:
            counts = [0, 0, 0]
            for val in diag:
                counts[val] += 1

            if counts[0] != counts[1] or counts[1] != counts[2]:
                return False, f"Anti-Diagonal k={k} (Length {L}) unbalanced: {counts}"

    # Check diagonals (Main Diagonals: j-i=k)
    # k ranges from -(n-1) to n-1 = 2
    for k in range(-(n - 1), n):
        diag = []
        for i in range(n):
            j = i + k
            if 0 <= j < n:
                diag.append(matrix[i][j])

        L = len(diag)
        if L > 0 and L % 3 == 0:
            counts = [0, 0, 0]
            for val in diag:
                counts[val] += 1

            if counts[0] != counts[1] or counts[1] != counts[2]:
                return False, f"Main-Diagonal k={k} (Length {L}) unbalanced: {counts}"

    return True, "All constraints met."

