import itertools

def is_latin_square(matrix):
    n = len(matrix)
    # Check rows
    for row in matrix:
        if len(set(row)) != n:
            return False
    # Check columns
    for j in range(n):
        col = [matrix[i][j] for i in range(n)]
        if len(set(col)) != n:
            return False
    return True

def solve_3x3():
    n = 3
    solutions = []
    # Try all possible matrices with entries 0, 1, 2
    for p in itertools.product(range(3), repeat=n*n):
        matrix = [list(p[i*n : (i+1)*n]) for i in range(n)]
        if is_latin_square(matrix):
            # Check diagonal D0: (0,0), (1,1), (2,2)
            d0 = [matrix[i][i] for i in range(n)]
            # Check anti-diagonal A4: (0,2), (1,1), (2,0)
            a4 = [matrix[i][n-1-i] for i in range(n)]

            if len(set(d0)) == n and len(set(a4)) == n:
                solutions.append(matrix)
    return solutions

print(solve_3x3())

